<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marketing</title><style>
:root{--bg:#0a0f1f;--side:#0f172a;--card:#151e33;--card2:#111a2e;--line:#2a3654;--text:#fff;--muted:#9fb0cc;--ok:#2ee6a6;--warn:#ffc21a;--accent:#8190ff;--danger:#ff6f87}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,Arial,sans-serif}.shell{display:grid;grid-template-columns:260px 1fr;min-height:100vh}.side{padding:28px 24px;border-right:1px solid var(--line);background:var(--side);position:sticky;top:0;height:100vh}.brand{font-size:30px;font-weight:800;margin-bottom:38px}.brand i{font-style:normal;color:var(--accent)}nav a{display:block;color:#c7d1e5;text-decoration:none;font-size:16px;margin:0 0 22px}nav a:hover{color:#fff}main{padding:40px 30px;min-width:0;max-width:1500px;width:100%}.lead{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.lead h1{font-size:34px;margin:0 0 12px}.lead p{color:var(--muted);font-size:17px;margin:0}.version{color:var(--muted);font-size:12px;border:1px solid var(--line);padding:8px 10px;border-radius:20px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}.card{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:20px;margin-bottom:14px}.metric{font-size:32px;font-weight:800;margin-top:10px}.muted{color:var(--muted)}h2{font-size:22px;margin:0 0 15px}.badge{display:inline-block;font-size:12px;border-radius:10px;padding:6px 9px;background:#173d35;color:var(--ok);white-space:nowrap}.pending{background:#3a3012;color:var(--warn)}.ready{background:#18354b;color:#81c8ff}.neutral{background:#202b44;color:#b9c7e2}.endpoint{font:12px ui-monospace,Consolas,monospace;background:#0d1425;padding:10px;border-radius:10px;overflow-wrap:anywhere}.split{display:grid;grid-template-columns:.85fr 1.15fr;gap:14px}.row,.platform{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:13px 0;border-bottom:1px solid var(--line)}.row:last-child,.platform:last-child{border:0}.conversations{display:grid;gap:10px}.conv{border:1px solid var(--line);border-radius:14px;padding:14px;background:var(--card2)}.conv-top{display:flex;justify-content:space-between;gap:12px}.who{font-weight:750}.client{color:#9cb0d6;font-size:12px;margin-top:4px}.msg{margin:12px 0;color:#dce4f2}.meta{font-size:11px;color:#7688aa}.tags{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.tagbtn,.btn{border:1px solid #344366;background:#172139;color:#dce5f7;border-radius:9px;padding:8px 11px;cursor:pointer;font-size:12px}.tagbtn.active,.btn.primary{background:#253566;border-color:#8291ff;color:#fff}.btn.ok{background:#173d35;border-color:#275c50;color:var(--ok)}.empty{color:var(--muted);padding:18px 0}.tiny{font-size:12px;color:#7585a4;margin-top:10px}.dir{font-size:11px;border:1px solid var(--line);padding:3px 6px;border-radius:8px;color:#9fb0cc}.ad{font-size:11px;color:#9db5ff;margin-top:8px}.form{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.input,.select{background:#0d1425;border:1px solid #344366;color:#fff;border-radius:9px;padding:9px 10px;min-height:38px}.input{min-width:190px}.select{min-width:170px}table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;color:#8fa0bf;font-weight:600;padding:10px 8px;border-bottom:1px solid var(--line)}td{padding:11px 8px;border-bottom:1px solid #26324e;vertical-align:middle}tr:last-child td{border-bottom:0}.statusline{display:flex;gap:7px;align-items:center}.dot{width:8px;height:8px;border-radius:50%;background:var(--ok)}.dot.warn{background:var(--warn)}.number-card{border:1px solid var(--line);border-radius:13px;padding:14px;margin-bottom:9px;background:var(--card2);display:grid;grid-template-columns:1fr auto;gap:14px}.number-title{font-weight:700}.number-meta{font-size:12px;color:#8fa0bf;margin-top:5px}.number-actions{display:flex;gap:7px;flex-wrap:wrap;align-items:center;justify-content:flex-end}.section-title{display:flex;align-items:center;justify-content:space-between;gap:12px}.mapping-grid{display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:8px}.mapping-grid .wide{grid-column:span 2}.notice{border:1px solid #344366;background:#10192c;border-radius:12px;padding:12px;color:#bac7de;font-size:13px;margin:12px 0}.oktext{color:var(--ok)}.warntext{color:var(--warn)}@media(max-width:1050px){.shell{grid-template-columns:1fr}.side{display:none}.grid{grid-template-columns:1fr 1fr}.split{grid-template-columns:1fr}.mapping-grid{grid-template-columns:1fr 1fr}}@media(max-width:620px){main{padding:22px 14px}.grid{grid-template-columns:1fr}.mapping-grid{grid-template-columns:1fr}.mapping-grid .wide{grid-column:span 1}.number-card{grid-template-columns:1fr}.number-actions{justify-content:flex-start}.input,.select{width:100%}}
</style></head><body><div class="shell"><aside class="side"><div class="brand">Marketing<i>.</i></div><nav><a href="#dashboard">Dashboard</a><a href="#clients">Clients</a><a href="#numbers">WhatsApp Numbers</a><a href="#conversations">Conversations</a><a href="#events">Event Mapping</a><a href="#platforms">Platforms</a></nav></aside><main id="dashboard"><div class="lead"><div><h1>Marketing Conversion Hub</h1><p>WhatsApp Business App → YCloud → Marketing tags → realtime ad signals</p></div><div class="version" id="version">Checking…</div></div><div class="grid"><div class="card"><div class="muted">Clients</div><div class="metric" id="clientsCount">—</div></div><div class="card"><div class="muted">WhatsApp Numbers</div><div class="metric" id="numbersCount">—</div></div><div class="card"><div class="muted">Conversations</div><div class="metric" id="conversationsCount">—</div></div><div class="card"><div class="muted">Events Today</div><div class="metric" id="eventsToday">—</div></div></div>
<div class="split"><section class="card"><h2>Receiver</h2><div class="platform"><span>YCloud webhook</span><span class="badge ready" id="receiver">Checking…</span></div><div class="platform"><span>YCloud Custom Events API</span><span class="badge" id="ycloudApi">Checking…</span></div><p class="muted">Webhook URL</p><div class="endpoint" id="endpoint"></div><p class="tiny" id="healthText"></p></section><section class="card"><h2>Current Flow</h2><div class="row"><span>Incoming customer message</span><span class="badge">Automatic</span></div><div class="row"><span>Reply from WhatsApp Business App</span><span class="badge">Automatic</span></div><div class="row"><span>Interested / Qualified / Purchased</span><span class="badge">Realtime</span></div><div class="row"><span>Platform-native optimization</span><span class="badge pending">Per client mapping</span></div></section></div>
<section class="card" id="clients"><div class="section-title"><h2>Clients</h2><span class="badge neutral">Multi-client</span></div><div class="form"><input class="input" id="clientName" placeholder="Client name"><button class="btn primary" onclick="addClient()">Add Client</button></div><div id="clientList" style="margin-top:12px"><div class="empty">Loading…</div></div></section>
<section class="card" id="numbers"><div class="section-title"><h2>WhatsApp Numbers</h2><span class="badge neutral">1–3 per client</span></div><div class="notice">Any number detected from YCloud appears here automatically as <b>Unassigned</b>. Assign it to the correct client once, then Marketing uses that relationship everywhere.</div><div id="numberList"><div class="empty">Loading…</div></div></section>
<section class="card" id="conversations"><div class="section-title"><h2>Incoming Conversations</h2><span class="badge neutral">Read-only</span></div><div class="tiny" style="margin:0 0 12px">Replies stay in WhatsApp Business App. Marketing only monitors and tags.</div><div class="conversations" id="conversationList"><div class="empty">Waiting for data…</div></div></section>
<section class="card" id="events"><div class="section-title"><h2>Event Mapping</h2><span class="badge neutral">Core funnel</span></div><table><thead><tr><th>Marketing Event</th><th>Trigger</th><th>YCloud</th><th>Native Ad Platform</th></tr></thead><tbody><tr><td>Conversation Started</td><td>First inbound message</td><td><span class="badge">Captured</span></td><td><span class="badge pending">Map per client</span></td></tr><tr><td>Interested</td><td>Manual tag</td><td><span class="badge">Realtime</span></td><td><span class="badge pending">Map per client</span></td></tr><tr><td>Qualified</td><td>Manual tag</td><td><span class="badge">Realtime</span></td><td><span class="badge pending">Map per client</span></td></tr><tr><td>Purchased</td><td>Manual tag</td><td><span class="badge">Realtime</span></td><td><span class="badge pending">Map per client</span></td></tr><tr><td>Lost</td><td>Manual tag</td><td><span class="badge neutral">Internal only</span></td><td><span class="badge neutral">No conversion</span></td></tr></tbody></table></section>
<section class="card" id="platforms"><div class="section-title"><h2>Platform Mappings</h2><span class="badge neutral">Configuration registry</span></div><div class="notice">This stores which ad account and event source belong to each client/WhatsApp number. Saving a mapping does <b>not</b> claim the native integration is active until its API connection is verified.</div><div class="mapping-grid"><select class="select" id="mapClient" onchange="updateMapNumbers()"><option value="">Select client</option></select><select class="select" id="mapNumber"><option value="">Select WhatsApp number</option></select><select class="select" id="mapPlatform"><option value="tiktok">TikTok</option><option value="meta">Meta</option><option value="google">Google Ads</option><option value="snapchat">Snapchat</option><option value="x">X</option><option value="linkedin">LinkedIn</option></select><input class="input" id="mapAccountName" placeholder="Ad account name"><input class="input" id="mapAccountId" placeholder="Ad account ID"><input class="input" id="mapEventSet" placeholder="Event set / dataset ID"><button class="btn primary" onclick="saveMapping()">Save Mapping</button></div><div id="mappingList" style="margin-top:14px"><div class="empty">No mappings yet.</div></div><div style="margin-top:16px"><div class="platform"><span>WhatsApp / YCloud</span><span class="badge">Connected</span></div><div class="platform"><span>Meta native conversions</span><span class="badge pending">Not mapped</span></div><div class="platform"><span>TikTok Messaging Events</span><span class="badge pending">Not mapped</span></div><div class="platform"><span>Google Ads</span><span class="badge pending">Not mapped</span></div><div class="platform"><span>Snapchat / X / LinkedIn</span><span class="badge pending">Not mapped</span></div></div></section>
</main></div><script>
const $=id=>document.getElementById(id);$('endpoint').textContent=location.origin+'/webhook.php';const S={clients:[],numbers:[],mappings:[],conversations:[]};function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function normPhone(s){return String(s||'').replace(/\D/g,'')}async function j(u,o){const r=await fetch(u,o);const x=await r.json();if(!r.ok)throw new Error(x.error||'request_failed');return x}function clientName(id){return S.clients.find(x=>x.id===id)?.name||'Unassigned'}function numberText(id){const n=S.numbers.find(x=>x.id===id);return n?(n.phone_number||n.waba_id||id):'All / none'}function findNumber(conv){return S.numbers.find(n=>normPhone(n.phone_number)===normPhone(conv.business_number)&&(String(n.waba_id||'')===String(conv.waba_id||'')))||S.numbers.find(n=>normPhone(n.phone_number)===normPhone(conv.business_number))}
async function load(){try{const [h,s,cl,nu,ma,co]=await Promise.all([j('api.php?action=health'),j('api.php?action=summary'),j('api.php?action=clients'),j('api.php?action=numbers'),j('api.php?action=platform_mappings'),j('api.php?action=conversations')]);S.clients=cl.clients||[];S.numbers=nu.numbers||[];S.mappings=ma.mappings||[];S.conversations=co.conversations||[];$('receiver').textContent=h.ok?'Ready':'Error';$('ycloudApi').textContent=h.ycloud_connected?'Connected':'Not connected';$('version').textContent='v'+h.version;$('healthText').textContent='Public receiver • persistent storage • all YCloud events logged';$('clientsCount').textContent=s.clients;$('numbersCount').textContent=s.whatsapp_numbers;$('conversationsCount').textContent=s.conversations;$('eventsToday').textContent=s.events_today;renderClients();renderNumbers();renderConversations();renderMappings();fillMapClients()}catch(e){$('version').textContent='Error';$('healthText').textContent=e.message}}
function renderClients(){if(!S.clients.length){$('clientList').innerHTML='<div class="empty">No clients configured yet.</div>';return}$('clientList').innerHTML='<table><thead><tr><th>Client</th><th>Status</th><th>WhatsApp Numbers</th></tr></thead><tbody>'+S.clients.map(c=>{const n=S.numbers.filter(x=>x.client_id===c.id).length;return `<tr><td><b>${esc(c.name)}</b></td><td><span class="badge">${esc(c.status||'active')}</span></td><td>${n}</td></tr>`}).join('')+'</tbody></table>'}
async function addClient(){const name=$('clientName').value.trim();if(!name)return;await j('api.php?action=client_save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});$('clientName').value='';await load()}
function clientOptions(selected=''){return '<option value="">Unassigned</option>'+S.clients.map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)}</option>`).join('')}
function renderNumbers(){if(!S.numbers.length){$('numberList').innerHTML='<div class="empty">No WhatsApp numbers detected yet.</div>';return}$('numberList').innerHTML=S.numbers.map(n=>`<div class="number-card"><div><div class="number-title">${esc(n.phone_number||'No phone')} ${n.detected?'<span class="badge ready">Detected</span>':''}</div><div class="number-meta">WABA: ${esc(n.waba_id||'—')} • Provider: ${esc(n.provider||'ycloud')} • ${n.client_id?'<span class="oktext">Assigned</span>':'<span class="warntext">Unassigned</span>'}</div></div><div class="number-actions"><input class="input" id="label_${esc(n.id)}" value="${esc(n.label||'WhatsApp')}" placeholder="Label"><select class="select" id="client_${esc(n.id)}">${clientOptions(n.client_id||'')}</select><button class="btn ok" onclick="saveNumber('${esc(n.id)}')">Save</button></div></div>`).join('')}
async function saveNumber(id){const n=S.numbers.find(x=>x.id===id);if(!n)return;await j('api.php?action=number_save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,phone_number:n.phone_number,waba_id:n.waba_id,provider:n.provider,label:$('label_'+id).value,client_id:$('client_'+id).value})});await load()}
function renderConversations(){const a=S.conversations;if(!a.length){$('conversationList').innerHTML='<div class="empty">No conversations received yet.</div>';return}$('conversationList').innerHTML=a.map(v=>{const n=findNumber(v),cn=n?clientName(n.client_id):'Unassigned';return `<div class="conv"><div class="conv-top"><div><div class="who">${esc(v.contact_name||v.customer_number)}</div><div class="client">Client: ${esc(cn)} • ${esc(v.business_number||'WhatsApp')} • ${esc(v.waba_id||'')}</div></div><div><span class="dir">${esc(v.last_direction||'')}</span><div class="meta">${v.last_message_at?new Date(v.last_message_at).toLocaleString():''}</div></div></div><div class="msg">${esc(v.last_message_text||'')}</div>${v.ctwa_clid?'<div class="ad">✓ Click-to-WhatsApp attribution captured</div>':''}<div class="tags">${['interested','qualified','purchased','lost'].map(t=>`<button class="tagbtn ${v.current_tag===t?'active':''}" onclick="tag('${v.id}','${t}')">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div></div>`}).join('')}
async function tag(id,tagName){await j('api.php?action=tag',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({conversation_id:id,tag:tagName})});await load()}
function fillMapClients(){const cur=$('mapClient').value;$('mapClient').innerHTML='<option value="">Select client</option>'+S.clients.map(c=>`<option value="${esc(c.id)}" ${c.id===cur?'selected':''}>${esc(c.name)}</option>`).join('');updateMapNumbers()}
function updateMapNumbers(){const cid=$('mapClient').value,cur=$('mapNumber').value;const nums=S.numbers.filter(n=>!cid||n.client_id===cid);$('mapNumber').innerHTML='<option value="">All / no specific number</option>'+nums.map(n=>`<option value="${esc(n.id)}" ${n.id===cur?'selected':''}>${esc(n.phone_number||n.waba_id)} — ${esc(n.label||'WhatsApp')}</option>`).join('')}
async function saveMapping(){const client_id=$('mapClient').value;if(!client_id){alert('Select a client first');return}await j('api.php?action=platform_mapping_save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_id,number_id:$('mapNumber').value,platform:$('mapPlatform').value,account_name:$('mapAccountName').value,account_id:$('mapAccountId').value,event_set_id:$('mapEventSet').value,status:'configured'})});$('mapAccountName').value='';$('mapAccountId').value='';$('mapEventSet').value='';await load()}
function renderMappings(){if(!S.mappings.length){$('mappingList').innerHTML='<div class="empty">No native platform mappings configured yet.</div>';return}$('mappingList').innerHTML='<table><thead><tr><th>Platform</th><th>Client</th><th>WhatsApp</th><th>Ad Account</th><th>Event Source</th><th>Status</th></tr></thead><tbody>'+S.mappings.map(m=>`<tr><td><b>${esc(m.platform)}</b></td><td>${esc(clientName(m.client_id))}</td><td>${esc(numberText(m.number_id))}</td><td>${esc(m.account_name||m.account_id||'—')}${m.account_name&&m.account_id?'<div class="tiny">'+esc(m.account_id)+'</div>':''}</td><td>${esc(m.event_set_id||'—')}</td><td><span class="badge neutral">${esc(m.status||'configured')}</span></td></tr>`).join('')+'</tbody></table>'}
load();setInterval(()=>{if(!document.hidden)load()},20000);
</script></body></html>
